};
global.set('icons', {
    'pow': {
        '0': 'power-off',
        '1': 'power-cycle'
    },
    'mode': {
        '0': 'stop',
        '1': 'play'
    }
}, 'memoryOnly');

return msg;

// Prepare UI form

msg.class = '';
msg.enabled = true;
msg.topic = '';
msg.payload = {
    'mail': '',
    'sn': ''
}

return msg;

// Check UI form and prepare Zendure Cloud API query

if (msg.payload.mail !== '' && msg.payload.sn !== '') {
    msg.topic = '';
    msg.url = 'https://app.zendure.tech/eu/developer/api/apply';
    msg.payload = {"snNumber":msg.payload.sn,"account":msg.payload.mail};

    return msg;
}

return;

// Parse MQTT message and store it in memory

// Check that payload is well formed
if (typeof msg.payload.sn !== 'string') {

    return;
}

// Get inverter data description
const inverter_describe = { ...(global.get('describe.inverter', 'memoryOnly') || {}) };

// Get inverter data default values
let inverter_template = { };
for (const key in inverter_describe) {
    inverter_template[key] = inverter_describe[key][0];
}

// Get inverter data
const inverter_data = { ...(global.get('inverter', 'memoryOnly') || {}) };

// Get inverter serial number
const sn = msg.payload.sn;
if (typeof inverter_data[sn] !== 'object') {
    inverter_data[sn] = {};
}

// Fill inverter data with all know keys
inverter_data[sn] = { ...inverter_template, ...inverter_data[sn] };

// Get battery data description
const battery_describe = { ...(global.get('describe.battery', 'memoryOnly') || {}) };

// Get battery data default values
let battery_template = { };
for (const key in battery_describe) {
    battery_template[key] = battery_describe[key][0];
}

// Get battery data
const battery_data = { ...(global.get('battery', 'memoryOnly') || {}) };

// Parse Zendure MQTT message
for (const key in msg.payload) {

    // battery data is in sub object
    if (key == 'packData') {

        // Parse inverter batteries data
        for (let i = 0; i < msg.payload[key].length; i++) {

            // Check data is well formed
            if (typeof msg.payload[key][i]['sn'] !== 'string') {

                continue;
            }

            // Shortcut
            let battery_sn = msg.payload[key][i]['sn'];

            // Create battery data if new
            if (typeof battery_data[battery_sn] !== 'object') {
                battery_data[battery_sn] = {};
            }

            // Parse battery data
            for (const b_key in msg.payload[key][i]) {

                // Convert in mV
                if (['maxVol', 'minVol', 'totalVol'].includes(b_key)) {
                    msg.payload[key][i][b_key] = msg.payload[key][i][b_key] * 10;
                }

                // Convert Kelvin in Celsuis
                if (b_key === 'maxTemp') {
                    msg.payload[key][i][b_key] = Math.round(msg.payload[key][i][b_key] * 10 - 2731) / 10;
                }
            }

            // Fill battery data with all know keys, and complte with received data
            battery_data[battery_sn] = { ...battery_template, ...battery_data[battery_sn], ...msg.payload[key][i], ...{ 'inverter': sn } };
        }
    }
    else {
        // Convert 10x Kelvin in °C
        if (key === 'hyperTmp') {
            msg.payload[key] = Math.round(msg.payload[key] - 2731) / 10;
        }
        if (typeof msg.payload[key] === 'boolean') {
            msg.payload[key] = msg.payload[key] === true ? 1 : 0;
        }

        // Fill inverter data with received data
        inverter_data[sn][key] = msg.payload[key];
    }
}

// Save data in memory file
global.set('inverter', inverter_data, 'memoryOnly');
global.set('battery', battery_data, 'memoryOnly');

// debug
msg.payload = {
    'inverter': inverter_data,
    'battery': battery_data
};

return msg;

if (typeof msg.payload !== 'object'
   || typeof msg.payload.code !== 'number'
   || msg.payload.number !== 200
   || typeof msg.payload.data !== 'object'
   || typeof msg.payload.data.appKey !== 'string'
