}
else {
   global.set('account', msg.payload.data, 'default');

   msg.payload = "Compte zendure valide";
}

return msg;

const account = { ...(global.get('account', 'default') || {}) };
if (typeof account.appKey !== 'string' || account.appKey === '') {
    node.status({ 'fill': 'red', 'text': 'settings nok' });

    return;
}

msg.topic = account.appKey + '/+/state';
msg.payload = '';
msg.broker = {};
