msg.broker.port = account.port;
msg.broker.username = account.appKey;
msg.broker.password = account.secret;

msg.broker.force = true;
msg.action = 'connect';

node.send([msg]);

delete msg.broker;

await new Promise(resolve => setTimeout(resolve, 1000));

msg.topic = account.appKey + '/+/state';
msg.payload = '';
msg.action = 'subscribe';
msg.qos = 1;

node.send([msg]);

node.status({fill:"green",shape:"ring",text:"settings ok"});

return;

// Prepare UI page data
flow.set('current_inverter', '', 'memoryOnly');
flow.set('current_battery', '', 'memoryOnly');

// Get known inverters
const inverters = { ...(global.get('inverter', 'memoryOnly') || { }) };

// Prepare message
msg.payload = '';
msg.class = '';
msg.enabled = true;
msg.options = [{
    'label': '',
    'value': '',
    'dropdown': 'name'
}];

let i = 1;
for(const sn in inverters) {
    msg.options[i++] = {
        'label': sn,
        'value': sn,
        'dropdown': 'name'
    }
}

// If there are no inverters
if (i == 1) {

    node.send([null, null]);
}
// If there is only one inverter
else if (i == 2) {
    msg.payload = msg.options[1]['value'];
    node.send([msg, null]);
    msg.class = 'remove';
    msg.enlabed = false;

    node.send([null, msg]);
}
// If there are more than one inverter
else {

    node.send([null, msg]);
}

return;

// Parse inverter data

const describe = { ...(global.get('describe.inverter', 'memoryOnly') || { }) };
const enums = { ...(global.get('describe.enum', 'memoryOnly') || { }) };

let i = 0;
let data = [];

for (const k in describe) {
    if (k in msg.payload) {
        let unit = describe[k][4];
        let value = msg.payload[k];

        if (unit === 'enum' && typeof enums[k] === 'object' && typeof enums[k][value.toString()] === 'string') {
            value = enums[k][value.toString()];
            unit = '';
        }
        else if (unit === 'b') {
            value = value === 1 ? 'On' : 'Off';
            unit = '';
        }

        data[i++] = {
            'name': describe[k][0],
            'value': value,
            'unit': unit
        };
    }
}

msg.payload = data;

return msg;

// Table bout main device information

const describe = { ...(global.get('describe.inverter', 'memoryOnly') || {}) };
const enums = { ...(global.get('describe.enum', 'memoryOnly') || {}) };

let res = [];
let i = 0;
let exists = false;
let state = 0;

if (typeof msg.payload['sn'] == 'string') {
    res[i++] = {
        'lbl': describe['sn'][0],
        'val': msg.payload['sn']
    };
    exists = true;
}

if (typeof msg.payload['packNum'] == 'number') {
    res[i++] = {
        'lbl': describe['packNum'][0],
        'val': msg.payload['packNum']
    };
    exists = true;
}

if (typeof msg.payload['packState'] == 'number') {
    res[i++] = {
        'lbl': describe['packState'][0],
        'val': enums['packState'][msg.payload['packState']]
    };
    exists = true;
    state = msg.payload['packState'];
}

if (typeof msg.payload['electricLevel'] === 'number') {
    res[i++] = {
        'lbl': describe['electricLevel'][0],
        'val': msg.payload['electricLevel'] + ' ' + describe['electricLevel'][4]
    };
    exists = true;
}

if (state === 1) {
    if (typeof msg.payload['remainInputTime'] == 'number' && msg.payload['remainInputTime'] !== 59940) {
        res[i++] = {
            'lbl': describe['remainInputTime'][0],
            'val': msg.payload['remainInputTime'] + ' ' + describe['remainInputTime'][4]
        };
        exists = true;
    }
    if (typeof msg.payload['packInputPower'] == 'number') {
        res[i++] = {
            'lbl': describe['packInputPower'][0],
            'val': msg.payload['packInputPower'] + ' ' + describe['packInputPower'][4]
        };
        exists = true;
    }
}

if (state === 2) {
    if (typeof msg.payload['remainOutTime'] == 'number' && msg.payload['remainOutTime'] !== 59940) {
        res[i++] = {
            'lbl': describe['remainOutTime'][0],
            'val': msg.payload['remainOutTime'] + ' ' + describe['remainOutTime'][4]
        };
        exists = true;
    }
    if (typeof msg.payload['outputPackPower'] == 'number') {
        res[i++] = {
            'lbl': describe['outputPackPower'][0],
            'val': msg.payload['outputPackPower'] + ' ' + describe['outputPackPower'][4]
        };
        exists = true;
    }
}

if (exists === true) {
    msg.payload = res;
    msg.class = '';

    return msg;
}

return;

// Table about main device settings

const describe = { ...(global.get('describe.inverter', 'memoryOnly') || {}) };
const enums = { ...(global.get('describe.enum', 'memoryOnly') || {}) };

let res = [];
let i = 0;
let exists = false;

if (typeof msg.payload['socSet'] == 'number') {
    res[i++] = {
        'lbl': describe['socSet'][0],
        'val': msg.payload['socSet'] + ' ' + describe['socSet'][4]
    };
    exists = true;
}

if (typeof msg.payload['inputLimit'] == 'number') {
    res[i++] = {
        'lbl': describe['inputLimit'][0],
        'val': msg.payload['inputLimit'] + ' ' + describe['inputLimit'][4]
    };
    exists = true;
}

if (typeof msg.payload['outputLimit'] == 'number') {
    res[i++] = {
        'lbl': describe['outputLimit'][0],
        'val': msg.payload['outputLimit'] + ' ' + describe['outputLimit'][4]
    };
    exists = true;
}

if (typeof msg.payload['inverseMaxPower'] == 'number') {
    res[i++] = {
        'lbl': describe['inverseMaxPower'][0],
        'val': msg.payload['inverseMaxPower'] + ' ' + describe['inverseMaxPower'][4]
    };
    exists = true;
}


if (exists === true) {
    msg.payload = res;
    msg.class = '';

    return msg;
}

return;

flow.set('current_battery', '', 'memoryOnly');

let i_sn = msg.payload.sn || '-';

const batteries = { ...(global.get('battery', 'memoryOnly') || { }) };
let data = {};
for (const b_sn in batteries) {
    if (batteries[b_sn]['inverter'] === i_sn) {
        data[b_sn] = batteries[b_sn];
    }
}

msg.payload = '';
msg.class = '';
msg.enabled = true;
msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'name'
}];

let i = 1;
for(const sn in data) {
    msg.options[i++] = {
        'label': sn,
        'value': sn,
        'dropdown':'name'
    }
}

